'use strict';
const MIN=60000;
function time(t){return new Date(t).toISOString().slice(0,16).replace('T',' ')}
function date(t){return time(t).slice(0,10)}
function parseCSV(s,stamp='start',session='day'){
 s=s.replace(/^\uFEFF/,'').trim();if(!s)throw Error('CSV 沒有資料');const norm=x=>String(x||'').normalize('NFKC').replace(/[\uFEFF\u200B-\u200D\u2060]/g,'').trim().replace(/^'/,'');let sepHint=s.match(/^sep=(.)[\r\n]+/i);if(sepHint)s=s.slice(sepHint[0].length);let first=s.split(/\r?\n/)[0],sep=sepHint?sepHint[1]:first.includes('\t')?'\t':first.includes(';')?';':',';
 let records=[],row=[],cell='',q=false;for(let i=0;i<s.length;i++){let ch=s[i];if(ch==='"'){if(q&&s[i+1]==='"'){cell+='"';i++;}else q=!q;}else if(ch===sep&&!q){row.push(cell.trim());cell='';}else if((ch==='\n'||ch==='\r')&&!q){if(ch==='\r'&&s[i+1]==='\n')i++;row.push(cell.trim());if(row.some(Boolean))records.push(row);row=[];cell='';}else cell+=ch;}if(q)throw Error('CSV 引號未成對');row.push(cell.trim());if(row.some(Boolean))records.push(row);
 let aliases=[['日期','交易日期','成交日期','交易日','date'],['時間','成交時間','time'],['開盤價','開盤','開','open','o'],['最高價','最高','高','high','h'],['最低價','最低','低','low','l'],['收盤價','收盤','收','close','c'],['成交量','成交量(口)','成交量(股)','總量','量','volume','vol','v']];let head=records[0].map(x=>norm(x).toLowerCase().replace(/\s/g,'').replace(/^#/,''));let hasHeader=aliases.some(list=>head.some(x=>list.includes(x))),cols=hasHeader?aliases.map(list=>head.findIndex(x=>list.includes(x))):[0,1,2,3,4,5,6];if(cols.some(x=>x<0))throw Error('標題列缺少必要欄位：'+aliases.filter((_,i)=>cols[i]<0).map(x=>x[0]).join('、')+'。讀到的標題：'+records[0].join(' | ').slice(0,160)+'；請選「自動辨識編碼」，或提供 CSV 原檔。');
 function parseDate(ds){let a=norm(ds).replace(/[年月.]/g,'/').replace(/日/g,'').replace(/[ T]00:00(?::00)?$/,'');let dm=a.match(/^(\d{3,4})[\/-](\d{1,2})[\/-](\d{1,2})$/)||a.match(/^(\d{4})(\d{2})(\d{2})$/);if(dm){let y=+dm[1];return [y<1911&&dm[1].length===3?y+1911:y,+dm[2],+dm[3]];}if(/^\d{5}(?:\.0+)?$/.test(a)&&+a>=20000&&+a<=100000){let d=new Date(Date.UTC(1899,11,30)+Number(a)*86400000);return [d.getUTCFullYear(),d.getUTCMonth()+1,d.getUTCDate()];}return null;}
 function parseTime(ts){let a=norm(ts),ampm=a.match(/上午|下午|am|pm/i);a=a.replace(/上午|下午|am|pm/ig,'').trim();let tm=a.match(/^(\d{1,2}):(\d{1,2})(?::(\d{1,2})(?:\.0+)?)?$/)||a.match(/^(\d{2})(\d{2})(\d{2})$/);if(tm){let h=+tm[1];if(ampm){if(h<1||h>12)return null;h=h%12+(/下午|pm/i.test(ampm[0])?12:0);}return [h,+tm[2],+(tm[3]||0)];}if(/^(?:0?\.\d+|0)$/.test(a)){let seconds=Number(a)*86400,rounded=Math.round(seconds);if(Math.abs(seconds-rounded)>.01||rounded>=86400)return null;return [Math.floor(rounded/3600),Math.floor(rounded/60)%60,rounded%60];}return null;}
 let out=[],seen=new Set(),filtered=0;for(let j=hasHeader?1:0;j<records.length;j++){let r=records[j],ds=r[cols[0]]||'',ts=r[cols[1]]||'',dm=parseDate(ds),tm=parseTime(ts);if(!dm||!tm)throw Error('第 '+(j+1)+' 列日期／時間無法辨識：日期「'+ds.slice(0,45)+'」、時間「'+ts.slice(0,45)+'」。'+(j===0&&!hasHeader?'第一列可能是未辨識的標題或編碼錯誤；請選自動辨識編碼。':'請提供 CSV 原檔以確認格式。'));let [yy,mo,dd]=dm,[hh,mm,ss]=tm,t=Date.UTC(yy,mo-1,dd,hh,mm,ss),check=new Date(t);if(check.getUTCFullYear()!==yy||check.getUTCMonth()!==mo-1||check.getUTCDate()!==dd||hh>23||mm>59||ss!==0)throw Error('第 '+(j+1)+' 列日期無效或不是整分鐘');if(stamp==='end')t-=MIN;let nums=cols.slice(2).map(k=>r[k]===undefined||r[k]===''?NaN:Number(norm(r[k]).replace(/,/g,'')));let [o,h,l,c,v]=nums;if(nums.some(x=>!Number.isFinite(x))||Math.min(o,h,l,c)<=0||v<0||h<Math.max(o,l,c)||l>Math.min(o,h,c))throw Error('第 '+(j+1)+' 列 OHLC／成交量不合理');if(seen.has(t))throw Error('重複時間：'+time(t)+'；請先移除重複或混合契約資料');seen.add(t);let dt=new Date(t),minute=dt.getUTCHours()*60+dt.getUTCMinutes();if(session==='day'&&(minute<525||minute>=825)){filtered++;continue;}out.push({t,o,h,l,c,v});}
 out.sort((a,b)=>a.t-b.t);if(!out.length)throw Error('沒有符合盤別的資料');let diff=out.slice(1).map((r,i)=>(r.t-out[i].t)/MIN).filter(x=>x<60);if(diff.length>3&&!diff.some(x=>x===1))throw Error('資料看起來不是 1 分 K，無法正確切換 1 分週期。請匯出 1 分 K。');let gaps=out.slice(1).filter((r,i)=>date(r.t)===date(out[i].t)&&r.t-out[i].t>MIN).length;return {rows:out,filtered,gaps};
}
function decodeCSV(buf,selected='auto'){let a=new Uint8Array(buf),enc=selected;if(a[0]===255&&a[1]===254)enc='utf-16le';else if(a[0]===254&&a[1]===255)enc='utf-16be';else if(a[0]===239&&a[1]===187&&a[2]===191)enc='utf-8';else if(enc==='auto'){try{return {text:new TextDecoder('utf-8',{fatal:true}).decode(buf),encoding:'UTF-8'};}catch(e){enc='big5';}}return {text:new TextDecoder(enc).decode(buf),encoding:enc.toUpperCase()};}

